promptBlocks.text:
{
  "task": "photorealistic composite image generation, amateur smartphone photo aesthetic",
  "model_intent": "reference-driven identity reconstruction with a human-height oversized device, shot like a casual iPhone vacation photo — not an editorial",
  "references": {
    "reference_1": {
      "role": "primary subject identity",
      "description": "Sole identity source. Preserve exact facial structure, proportions, curly dark-brown hair, mustache with light chin stubble, and the black wayfarer-style sunglasses exactly as worn in this image. The sunglasses must stay on. Ignore this image's clothing, background and lighting entirely."
    },
    "reference_2": {
      "role": "phone screen content",
      "description": "Recreate this screenshot exactly as the phone's screen content. Preserve layout, text, spacing, proportions and colors precisely, mapped flat onto the screen with no distortion."
    }
  },
  "scene_description": {
    "environment": "a wooden bathing pier (lido jetty) on the Amalfi Coast, Italy — weathered sun-bleached planks, simple metal railings, striped umbrellas and pastel cliffside houses stacked on the rocks behind",
    "background_life": "a few real swimmers in the sea behind the pier — one mid-dive, one wading in, wet heads bobbing in the water, none looking at the camera",
    "sea": "clear turquoise-to-deep-blue Tyrrhenian water with small ripples and sun glitter",
    "time_of_day": "late morning, bright Mediterranean sun, hard summer light",
    "composition": "the subject and a human-height vertical smartphone stand side by side on the pier, two equal vertical masses in the frame"
  },
  "subject_handling": {
    "identity_lock": true,
    "sunglasses_lock": "black wayfarer sunglasses from reference_1 stay on, sharp reflections of sea and sky in the lenses",
    "pose": "relaxed confident stance next to the giant phone, weight on one leg, facing camera",
    "expression": "faint amused half-smile, vacation ease, not posed-serious",
    "interaction": "one palm resting flat against the phone's side edge at his chest height — the device is far too large to hold, he leans on it like leaning on a wall, the other hand loose at his side",
    "scale_relationship": "the phone is as tall as the man — its top edge level with the top of his head, a human-height monolith standing beside him",
    "skin": "natural skin texture, slight summer tan lines, no smoothing"
  },
  "wardrobe_styling": {
    "outfit_source": "Kith official summer collection styling",
    "top": "premium sleeveless cotton tank in a washed neutral tone, boxy relaxed cut, heavyweight slub fabric with visible knit texture",
    "bottom": "Kith-style swim shorts, mid-thigh length, tailored nylon with an allover subtle print, drawstring waist, fabric moving slightly in the sea breeze",
    "footwear": "chunky Crocs clogs in a bold color, worn confidently",
    "footwear_accessories": "the Crocs ventilation holes are filled with Jibbitz-style charms — small enamel pin badges, tiny figurines and plug-in tokens, a dense playful mix, each charm clearly seated in its own hole",
    "branding_rules": "no visible logos on clothing, footwear branding allowed",
    "fabric_detail": "real textile weight, natural folds, sun hitting the fabric honestly"
  },
  "phone_handling": {
    "device": "iPhone 17 Pro",
    "scale_priority": "human-height monolith scale — the phone matches the subject's full standing height, roughly 180cm tall, dominating the frame equally with him",
    "position": "standing vertically on the wooden pier planks, planted like a sculpture, the planks subtly reflecting its glass",
    "orientation": "fully frontal, screen facing camera",
    "material_detail": "realistic glass with sky and sea reflections along the edges, brushed titanium frame, visible thickness proportional to its giant size, camera housing edge visible on the back corner",
    "weight_realism": "the pier planks bear its weight believably — a heavy grounded presence, not floating",
    "shadow_behavior": "one long hard midday shadow cast across the planks and partially over the subject, consistent with the sun direction"
  },
  "phone_screen_content": {
    "screen_state": "active",
    "content_mapping": "place reference_2 exactly onto the phone screen without distortion or reinterpretation",
    "ui_realism": "screen brightness fighting the sunlight — slightly washed out under direct sun, faint glare streak across one corner, subtle fingerprint smudges near the edge"
  },
  "lighting": {
    "key_light": "hard direct Mediterranean midday sun from above and slightly behind camera",
    "ambient_light": "bright bounce from the white pier planks and the water",
    "shadow_quality": "short hard summer shadows, deep but with soft bounce fill from the sea"
  },
  "camera": {
    "style": "amateur smartphone photo, taken like an iPhone photo by a friend standing a few steps away, no professional effects",
    "lens": "composed like an iPhone 15 Pro 26mm f/1.8 main camera shot",
    "focus": "crisp sharp focus across the entire frame, realistic colors, clean HDR look with slight computational sharpening",
    "framing": "eye-level full-body shot from a few steps further back so both the man and the human-height phone fit fully in frame with the pier and sea behind, horizon straight, framing very slightly off-center like a quick real snapshot",
    "imperfections": "tiny sun flare at the top edge, faint HDR halo where the white wall meets the sky"
  },
  "quality_constraints": {
    "look": "must read as a real photo from someone's camera roll — not an editorial, not CGI, not a render",
    "no_cartoon": true,
    "no_anime": true,
    "no_plastic_skin": true,
    "no_digital_smoothing": true,
    "no_text_or_watermark_outside_phone_screen": true
  },
  "final_instruction": "The image must look like a real iPhone vacation photo taken on an Amalfi Coast bathing pier: the subject, wearing his black wayfarer sunglasses, a Kith-style sleeveless summer tank, printed swim shorts and charm-loaded Crocs, leans one palm against a human-height iPhone 17 Pro standing beside him — as tall as he is — displaying the exact reference screenshot, while swimmers splash in the turquoise sea behind them."
}
